content.solution_code:
class Character {
    constructor(name, health) {
        this.name = name;
        this.health = health;
    }

    performAction() {
        return `${this.name} stands ready.`;
    }
}

class Warrior extends Character {
    constructor(name, health, weapon) {
        super(name, health);
        this.weapon = weapon;
    }

    #getWeaponDescription() {
        return `swings their ${this.weapon}`;
    }

    performAction() {
        return `${this.name} ${this.#getWeaponDescription()}!`
    }
}

class Mage extends Character {
    constructor(name, health, spell) {
        super(name, health);
        this.spell = spell;
    }

    #getSpellDescription() {
        return `casts ${this.spell}`;
    }

    performAction() {
        return `${this.name} ${this.#getSpellDescription()}!`;
    }
}

